/**
 * @description Builds the outbound JSON body. Payload Source Selected Fields (default): the transaction Id, event,
 * record Id, object and the event's selected fields (Payload Fields, parent paths up to 5 lookups), one query per event.
 * Payload Source Apex Class: the event's payload class builds the bodies (IntegrationHubPayloadClass).
 * The parts that need no records (base body, field values; paths in IntegrationHubPayloadPaths) are public so they can
 * be tested without data.
 * @group Integration Hub
 */
public with sharing class IntegrationHubPayload {

    /** @description Payload Source value for bodies built by an Apex class. */
    public static final String SOURCE_APEX = 'Apex Class';
    /** @description Default JSON key of the transaction Id. */
    public static final String DEFAULT_TXN_KEY = 'sfTransactionId';

    /**
     * @description Bodies and errors, by transaction Id.
     */
    public class Result {
        /** @description JSON body per transaction Id. */
        public Map<Id, String> bodies = new Map<Id, String>();
        /** @description Error per transaction Id (configuration problems). */
        public Map<Id, String> errors = new Map<Id, String>();
    }

    /**
     * @description Builds the bodies of transactions of one event.
     * @param ev the event (Payload_Source__c, Payload_Fields__c, Payload_Class__c, Related_Object__c, Transaction_Id_Key__c)
     * @param txns the transactions
     * @return the bodies and errors
     */
    public static Result build(IH_Event__c ev, List<IH_Transaction__c> txns) {
        if (txns.isEmpty()) {
            return new Result();
        }
        if (ev.Payload_Source__c == SOURCE_APEX) {
            return IntegrationHubPayloadClass.build(ev, txns);
        }
        return selectedFields(ev, txns);
    }

    /**
     * @description The JSON key that carries the transaction Id.
     * @param ev the event
     * @return its Transaction Id Key, or sfTransactionId
     */
    public static String txnKeyOf(IH_Event__c ev) {
        return ev == null || String.isBlank(ev.Transaction_Id_Key__c) ? DEFAULT_TXN_KEY : ev.Transaction_Id_Key__c;
    }

    /**
     * @description The base body of one transaction: transaction Id, event, record Id and object. Needs no data.
     * @param txnKey the JSON key of the transaction Id
     * @param t the transaction
     * @return the body
     */
    public static Map<String, Object> baseBody(String txnKey, IH_Transaction__c t) {
        return new Map<String, Object>{
            txnKey => t.Id, 'eventName' => t.Event_Name__c, 'recordId' => t.Related_Record_Id__c, 'object' => t.Related_Object__c
        };
    }

    /**
     * @description The selected field values of one record, by path. Needs no data: the record can be built in memory.
     * Empty values are left out.
     * @param rec the record (may be null)
     * @param paths the field paths
     * @return the values
     */
    public static Map<String, Object> fieldValues(SObject rec, List<String> paths) {
        Map<String, Object> values = new Map<String, Object>();
        for (String path : paths) {
            Object value = IntegrationHubPayloadPaths.read(rec, path);
            if (value != null) {
                values.put(path, value);
            }
        }
        return values;
    }

    private static Result selectedFields(IH_Event__c ev, List<IH_Transaction__c> txns) {
        Result result = new Result();
        String objectName = String.isBlank(ev.Related_Object__c) ? txns[0].Related_Object__c : ev.Related_Object__c;
        List<String> paths = IntegrationHubPayloadPaths.split(ev.Payload_Fields__c);
        String problem = IntegrationHubPayloadPaths.invalid(objectName, paths);
        Map<Id, SObject> records = problem == null && !paths.isEmpty() ? load(objectName, paths, txns) : new Map<Id, SObject>();
        String txnKey = txnKeyOf(ev);
        for (IH_Transaction__c t : txns) {
            if (problem == null) {
                Map<String, Object> body = baseBody(txnKey, t);
                if (!paths.isEmpty()) {
                    body.put('fields', fieldValues(records.get((Id) t.Related_Record_Id__c), paths));
                }
                result.bodies.put(t.Id, JSON.serialize(body, true));
            } else {
                result.errors.put(t.Id, problem);
            }
        }
        return result;
    }

    private static Map<Id, SObject> load(String objectName, List<String> paths, List<IH_Transaction__c> txns) {
        Set<String> ids = new Set<String>();
        for (IH_Transaction__c t : txns) {
            ids.add(t.Related_Record_Id__c);
        }
        Set<String> fields = new Set<String>{ 'id' };
        for (String path : paths) {
            fields.add(String.escapeSingleQuotes(path.toLowerCase()));
        }
        String soql = 'SELECT ' + String.join(new List<String>(fields), ', ') + ' FROM ' + String.escapeSingleQuotes(objectName)
            + ' WHERE Id IN :ids';
        return new Map<Id, SObject>(IntegrationHubData.query(soql, new Map<String, Object>{ 'ids' => ids }));
    }
}
